50: /**
51:  * Set the system properties, org.sqlite.lib.path, org.sqlite.lib.name, appropriately so that the
52:  * SQLite JDBC driver can find *.dll, *.dylib and *.so files, according to the current OS (win,
53:  * linux, mac).
54:  *
55:  * <p>The library files are automatically extracted from this project's package (JAR).
56:  *
57:  * <p>usage: call {@link #initialize()} before using SQLite JDBC driver.
58:  *
59:  * @author leo
60:  */
61: @AndroidSignatureIgnore(explanation = "The loader is not used on Android")
62: public class SQLiteJDBCLoader {
63:     private static final Logger logger = LoggerFactory.getLogger(SQLiteJDBCLoader.class);
64: 
65:     private static final String LOCK_EXT = ".lck";
66:     private static boolean extracted = false;
67: 
68:     /**
69:      * Loads SQLite native JDBC library.
70:      *
71:      * @return True if SQLite native library is successfully loaded; false otherwise.
72:      */
73:     public static synchronized boolean initialize() throws Exception {
74:         // only cleanup before the first extract
75:         if (!extracted) {
76:             cleanup();
77:         }
78:         loadSQLiteNativeLibrary();
79:         return extracted;
80:     }
81: 
82:     private static File getTempDir() {
83:         return new File(
84:                 System.getProperty("org.sqlite.tmpdir", System.getProperty("java.io.tmpdir")));
85:     }
86: 
87:     /**
88:      * Deleted old native libraries e.g. on Windows the DLL file is not removed on VM-Exit (bug #80)
89:      */
90:     static void cleanup() {
91:         String searchPattern = "sqlite-" + getVersion();
92: 
93:         try (Stream<Path> dirList = Files.list(getTempDir().toPath())) {
94:             dirList.filter(
95:                             path ->
96:                                     !path.getFileName().toString().endsWith(LOCK_EXT)
97:                                             && path.getFileName()
98:                                                     .toString()
99:                                                     .startsWith(searchPattern))
100:                     .forEach(
101:                             nativeLib -> {
102:                                 Path lckFile = Paths.get(nativeLib + LOCK_EXT);
103:                                 if (Files.notExists(lckFile)) {
104:                                     try {
105:                                         Files.delete(nativeLib);
106:                                     } catch (Exception e) {
107:                                         logger.error(() -> "Failed to delete old native lib", e);
108:                                     }
109:                                 }
110:                             });
111:         } catch (IOException e) {
112:             logger.error(() -> "Failed to open directory", e);
113:         }
114:     }
115: 
116:     /**
117:      * Checks if the SQLite JDBC driver is set to native mode.
118:      *
119:      * @return True if the SQLite JDBC driver is set to native Java mode; false otherwise.
120:      */
121:     public static boolean isNativeMode() throws Exception {
122:         // load the driver
123:         initialize();
124:         return extracted;
125:     }
126: 
127:     /**
128:      * Computes the MD5 value of the input stream.
129:      *
130:      * @param input InputStream.
131:      * @return Encrypted string for the InputStream.
132:      * @throws IOException
133:      * @throws NoSuchAlgorithmException
134:      */
135:     static String md5sum(InputStream input) throws IOException {
136:         BufferedInputStream in = new BufferedInputStream(input);
137: 
138:         try {
139:             MessageDigest digest = java.security.MessageDigest.getInstance("MD5");
140:             DigestInputStream digestInputStream = new DigestInputStream(in, digest);
141:             for (; digestInputStream.read() >= 0; ) {}
142: 
143:             ByteArrayOutputStream md5out = new ByteArrayOutputStream();
144:             md5out.write(digest.digest());
145:             return md5out.toString();
146:         } catch (NoSuchAlgorithmException e) {
147:             throw new IllegalStateException("MD5 algorithm is not available: " + e);
148:         } finally {
149:             in.close();
150:         }
151:     }
152: 
153:     private static boolean contentsEquals(InputStream in1, InputStream in2) throws IOException {
154:         if (!(in1 instanceof BufferedInputStream)) {
155:             in1 = new BufferedInputStream(in1);
156:         }
157:         if (!(in2 instanceof BufferedInputStream)) {
158:             in2 = new BufferedInputStream(in2);
159:         }
160: 
161:         int ch = in1.read();
162:         while (ch != -1) {
163:             int ch2 = in2.read();
164:             if (ch != ch2) {
165:                 return false;
166:             }
167:             ch = in1.read();
168:         }
169:         int ch2 = in2.read();
170:         return ch2 == -1;
171:     }
172: 
173:     /**
174:      * Extracts and loads the specified library file to the target folder
175:      *
176:      * @param libFolderForCurrentOS Library path.
177:      * @param libraryFileName Library name.
178:      * @param targetFolder Target folder.
179:      * @return
180:      */
181:     private static boolean extractAndLoadLibraryFile(
182:             String libFolderForCurrentOS, String libraryFileName, String targetFolder)
183:             throws FileException {
184:         String nativeLibraryFilePath = libFolderForCurrentOS + "/" + libraryFileName;
185:         // Include architecture name in temporary filename in order to avoid conflicts
186:         // when multiple JVMs with different architectures running at the same time
187:         String uuid = UUID.randomUUID().toString();
188:         String extractedLibFileName =
189:                 String.format("sqlite-%s-%s-%s", getVersion(), uuid, libraryFileName);
190:         String extractedLckFileName = extractedLibFileName + LOCK_EXT;
191: 
192:         Path extractedLibFile = Paths.get(targetFolder, extractedLibFileName);
193:         Path extractedLckFile = Paths.get(targetFolder, extractedLckFileName);
194: 
195:         try {
196:             // Extract a native library file into the target directory
197:             try (InputStream reader = getResourceAsStream(nativeLibraryFilePath)) {
198:                 if (Files.notExists(extractedLckFile)) {
199:                     Files.createFile(extractedLckFile);
200:                 }
201: 
202:                 Files.copy(reader, extractedLibFile, StandardCopyOption.REPLACE_EXISTING);
203:             } finally {
204:                 // Delete the extracted lib file on JVM exit.
205:                 extractedLibFile.toFile().deleteOnExit();
206:                 extractedLckFile.toFile().deleteOnExit();
207:             }
208: 
209:             // Set executable (x) flag to enable Java to load the native library
210:             extractedLibFile.toFile().setReadable(true);
211:             extractedLibFile.toFile().setWritable(true, true);
212:             extractedLibFile.toFile().setExecutable(true);
213: 
214:             // Check whether the contents are properly copied from the resource folder
215:             {
216:                 try (InputStream nativeIn = getResourceAsStream(nativeLibraryFilePath);
217:                         InputStream extractedLibIn = Files.newInputStream(extractedLibFile)) {
218:                     if (!contentsEquals(nativeIn, extractedLibIn)) {
219:                         throw new FileException(
220:                                 String.format(
221:                                         "Failed to write a native library file at %s",
222:                                         extractedLibFile));
223:                     }
224:                 }
225:             }
226:             return loadNativeLibrary(targetFolder, extractedLibFileName);
227:         } catch (IOException e) {
228:             logger.error(() -> "Unexpected IOException", e);
229:             return false;
230:         }
231:     }
232: 
233:     // Replacement of java.lang.Class#getResourceAsStream(String) to disable sharing the resource
234:     // stream
235:     // in multiple class loaders and specifically to avoid
236:     // https://bugs.openjdk.java.net/browse/JDK-8205976
237:     private static InputStream getResourceAsStream(String name) {
