36: /**
37:  * Provides OS name and architecture name.
38:  *
39:  * @author leo
40:  */
41: public class OSInfo {
42:     protected static ProcessRunner processRunner = new ProcessRunner();
43:     private static final HashMap<String, String> archMapping = new HashMap<>();
44: 
45:     public static final String X86 = "x86";
46:     public static final String X86_64 = "x86_64";
47:     public static final String IA64_32 = "ia64_32";
48:     public static final String IA64 = "ia64";
49:     public static final String PPC = "ppc";
50:     public static final String PPC64 = "ppc64";
51:     public static final String RISCV64 = "riscv64";
52: 
53:     static {
54:         // x86 mappings
55:         archMapping.put(X86, X86);
56:         archMapping.put("i386", X86);
57:         archMapping.put("i486", X86);
58:         archMapping.put("i586", X86);
59:         archMapping.put("i686", X86);
60:         archMapping.put("pentium", X86);
61: 
62:         // x86_64 mappings
63:         archMapping.put(X86_64, X86_64);
64:         archMapping.put("amd64", X86_64);
65:         archMapping.put("em64t", X86_64);
66:         archMapping.put("universal", X86_64); // Needed for openjdk7 in Mac
67: 
68:         // Itanium 64-bit mappings
69:         archMapping.put(IA64, IA64);
70:         archMapping.put("ia64w", IA64);
71: 
